.btn-secondary { background: var(--color-surface); color: var(--color-text); border-color: var(--rule); }
.btn-ghost { box-shadow: none; }
.blueprint { border-radius: 8px; background: var(--color-surface); }
.blueprint .corner { display: none; }
.duotone { border-radius: 6px; }
.hero-video__media { border-radius: 6px; }
.duotone::after, .duotone::before { display: none; }
.duotone img, .duotone video { filter: none; mix-blend-mode: normal; }
.card, .dialog, .input, .seg { border-radius: 8px; }
.tag { border-radius: 5px; font-size: 11px; white-space: nowrap; overflow-wrap: normal; }
.table { font-size: 13px; line-height: 20px; }
.table th { font: 500 12px/18px var(--font-body); letter-spacing: 0; text-transform: none; }
.table td { padding: 10px 7px; overflow-wrap: anywhere; }
.table th { padding: 10px 7px; }
.pathsw label { border-radius: 8px; font: 500 14px/20px var(--font-body); padding: 10px 14px; letter-spacing: 0; }
